items.body:
Currently, Casdoor’s DeleteSession only deletes a session for a specific (owner, name, application) combination. This causes problems in setups where:

- Single sign-on (SSO) is enabled across multiple applications.
- A user logs in once and sessions are shared across apps.
- When the user logs out, Casdoor only deletes the session for one application, leaving other sessions active.

My working code:
```go
func DeleteSession(id string, onlyUseOrg bool) (bool, error) {
	owner, name, application := util.GetOwnerAndNameAndOtherFromId(id)
	session, err := GetSingleSession(id)

	if owner == CasdoorOrganization && application == CasdoorApplication {
		if err != nil {
			return false, err
		}
	}

	var affected int64
	if onlyUseOrg {
		// Get all sessions for this organization and user (without application filter)
		sessions := []*Session{}
		err = ormer.Engine.Where("owner = ? AND name = ?", owner, name).Find(&sessions)
		if err != nil {
			return false, err
		}

		// Delete all session IDs from beego session store
		for _, sess := range sessions {
			if sess.SessionId != nil {
				DeleteBeegoSession(sess.SessionId)
			}
		}

		// Delete all sessions from database
		affected, err = ormer.Engine.Where("owner = ? AND name = ?", owner, name).Delete(&Session{})
		if err != nil {
			return false, err
		}
	} else {
		affected, err = ormer.Engine.ID(core.PK{owner, name, application}).Delete(&Session{})
		if err != nil {
			return false, err
		}

		if session != nil {
			DeleteBeegoSession(session.SessionId)
		}
	}

	return affected != 0, nil
}

```
